# Agrega el script de carga de usuarios de clubes (operaciones). Ejecutar desde la raiz del repo.
$ErrorActionPreference = 'Stop'
$b64 = ""
$dest = Join-Path (Get-Location) 'backend\prisma\cargar_usuarios_operaciones.js'
[IO.File]::WriteAllBytes($dest, [Convert]::FromBase64String($b64))
$pkg = Join-Path (Get-Location) 'backend\package.json'
$t = [IO.File]::ReadAllText($pkg)
if ($t -notmatch 'cargar:usuarios-operaciones') {
  $t = $t -replace '("migrate:operaciones": "node prisma/migrate_operaciones.js")', ('$1,' + [Environment]::NewLine + '    "cargar:usuarios-operaciones": "node prisma/cargar_usuarios_operaciones.js"')
  [IO.File]::WriteAllText($pkg, $t)
}
Write-Host 'Listo. Siguiente: crear backend\.env con DATABASE_URL de produccion y correr: cd backend; npm run cargar:usuarios-operaciones'